'use client';

import React from 'react';

/** A single item in the dropdown menu. */
export interface DropdownItem {
  /** Unique key. */
  value: string;
  /** Display label. */
  label: string;
  /** Whether this is a destructive action. */
  destructive?: boolean;
  /** Render a separator before this item. */
  separator?: boolean;
}

/** Props for the {@link Dropdown} component. */
export interface DropdownProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'onSelect'> {
  /** Menu items. */
  items: DropdownItem[];
  /** Whether the dropdown is open (controlled). */
  open?: boolean;
  /** Called when an item is selected. */
  onSelect?: (value: string) => void;
  /** Called when open state changes. */
  onOpenChange?: (open: boolean) => void;
  /** The trigger element rendered as the dropdown button. */
  trigger: React.ReactNode;
  /** Additional CSS class names. */
  className?: string;
}

/**
 * Menu dropdown with dither overlay on the content panel.
 * Manages open/close state and renders items from the `items` prop.
 */
export const Dropdown = React.forwardRef<HTMLDivElement, DropdownProps>(
  ({ items, open: controlledOpen, onSelect, onOpenChange, trigger, className, ...rest }, ref) => {
    const [internalOpen, setInternalOpen] = React.useState(false);
    const isOpen = controlledOpen ?? internalOpen;
    const wrapperRef = React.useRef<HTMLDivElement>(null);

    const toggle = React.useCallback(() => {
      const next = !isOpen;
      if (controlledOpen === undefined) setInternalOpen(next);
      onOpenChange?.(next);
    }, [isOpen, controlledOpen, onOpenChange]);

    const close = React.useCallback(() => {
      if (controlledOpen === undefined) setInternalOpen(false);
      onOpenChange?.(false);
    }, [controlledOpen, onOpenChange]);

    // Close on outside click
    React.useEffect(() => {
      if (!isOpen) return;
      const handler = (e: MouseEvent) => {
        if (wrapperRef.current && !wrapperRef.current.contains(e.target as Node)) {
          close();
        }
      };
      document.addEventListener('mousedown', handler);
      return () => document.removeEventListener('mousedown', handler);
    }, [isOpen, close]);

    return (
      <div
        ref={(node) => {
          (wrapperRef as React.MutableRefObject<HTMLDivElement | null>).current = node;
          if (typeof ref === 'function') ref(node);
          else if (ref) (ref as React.MutableRefObject<HTMLDivElement | null>).current = node;
        }}
        className={`sk-dropdown${className ? ` ${className}` : ''}`}
        {...rest}
      >
        <span onClick={toggle} style={{ cursor: 'pointer' }}>{trigger}</span>
        <div className="sk-dropdown__content" data-open={isOpen ? '' : undefined}>
          {items.map((item) => (
            <React.Fragment key={item.value}>
              {item.separator && <div className="sk-dropdown__separator" />}
              <div
                className={`sk-dropdown__item${item.destructive ? ' sk-dropdown__item--destructive' : ''}`}
                role="menuitem"
                onClick={() => {
                  onSelect?.(item.value);
                  close();
                }}
              >
                {item.label}
              </div>
            </React.Fragment>
          ))}
        </div>
      </div>
    );
  },
);

Dropdown.displayName = 'Dropdown';

/**
 * skeehn — Dropdown Component
 *
 * @component sk-dropdown
 * @variants  default | [data-variant="pixel"] | [data-variant="retro"] | [data-variant="ascii"]
 * @states    [open] | [data-open] | [data-loading] | [data-skeleton]
 * @slots     __content | __item | __separator
 * @a11y      Keyboard nav, focus management, aria-expanded
 * @print     Hidden (menus are interactive only)
 */

.sk-dropdown { position: relative; display: inline-flex; font-family: var(--sk-font-mono); }
.sk-dropdown__content { position: absolute; top: calc(100% + var(--sk-space-1)); left: 0; min-width: 12rem; padding: var(--sk-space-1); background: hsl(var(--sk-background)); border: 2px solid hsl(var(--sk-foreground)); border-radius: var(--sk-radius); z-index: var(--sk-z-dropdown); opacity: 0; visibility: hidden; transform: translateY(-0.25rem); transition: all var(--sk-transition-fast); }
.sk-dropdown__content::before { content: ""; position: absolute; inset: 0; background-image: var(--sk-dither-pattern); background-repeat: repeat; opacity: calc(var(--sk-dither-opacity, 0.15) * 0.3); pointer-events: none; border-radius: inherit; }
.sk-dropdown[open] .sk-dropdown__content, .sk-dropdown__content[data-open] { opacity: 1; visibility: visible; transform: translateY(0); }
.sk-dropdown__item { padding: var(--sk-space-2) var(--sk-space-3); font-size: var(--sk-font-size-sm); border-radius: var(--sk-radius); cursor: pointer; position: relative; z-index: 1; transition: background var(--sk-transition-fast); letter-spacing: 0.01em; }
.sk-dropdown__item:hover { background: hsl(var(--sk-secondary)); }
.sk-dropdown__separator { height: 1px; margin: var(--sk-space-1) 0; background: hsl(var(--sk-border-color)); }
.sk-dropdown__item--destructive { color: hsl(var(--sk-destructive)); }
.sk-dropdown__item--destructive:hover { background: hsl(var(--sk-destructive) / 0.1); }

/* Micro-interactions */
.sk-dropdown__item:active { transform: translateY(1px); }
.sk-dropdown__item:focus-visible { outline: var(--sk-focus-ring); outline-offset: -2px; }

/* Pixel variant */
.sk-dropdown[data-variant="pixel"] .sk-dropdown__content { border: 3px solid hsl(var(--sk-foreground)); box-shadow: 4px 4px 0 hsl(var(--sk-foreground)); }

/* Retro variant */
.sk-dropdown[data-variant="retro"] .sk-dropdown__content { box-shadow: 0 0 12px hsl(var(--sk-foreground) / 0.1); }
.sk-dropdown[data-variant="retro"] .sk-dropdown__content::before { background-image: var(--sk-dither-scanlines); background-size: 100% 4px; opacity: 0.03; }

/* ASCII variant */
.sk-dropdown[data-variant="ascii"] .sk-dropdown__content { border: 1px dashed hsl(var(--sk-border-color)); background: hsl(var(--sk-background)); }
.sk-dropdown[data-variant="ascii"] .sk-dropdown__content::before { display: none; }

/* Loading */
.sk-dropdown[data-loading] .sk-dropdown__item { pointer-events: none; opacity: 0.5; }

/* Skeleton */
.sk-dropdown[data-skeleton] .sk-dropdown__item { color: transparent; background: linear-gradient(90deg, hsl(var(--sk-muted)) 25%, hsl(var(--sk-accent)) 50%, hsl(var(--sk-muted)) 75%); background-size: 200% 100%; animation: sk-card-shimmer 1.8s ease-in-out infinite; margin-bottom: var(--sk-space-1); border-radius: var(--sk-radius); }

@media print { .sk-dropdown__content { display: none; } }

@media (prefers-reduced-motion: reduce) {
  .sk-dropdown__content { transition: none; }
  .sk-dropdown__item { transition: none; transform: none; }
  .sk-dropdown[data-skeleton] .sk-dropdown__item { animation: none; background: hsl(var(--sk-muted)); }
}
